"use client"

/** Clean-room discovery panel. Lists, quotes, and a scrubbable waveform. */

import * as React from "react"
import { AlertTriangle, Play } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { AudioPlayer, type AudioPlayerHandle } from "@/components/ui/audio-player"

export type DiscoveryNote = {
  id: string
  text: string
  /** Seconds into the recording. */
  at?: number
}

export type DiscoveryColumn = {
  id: string
  title: string
  items: readonly DiscoveryNote[]
}

export type DiscoveryUnknown = {
  id: string
  text: string
  badge: string
}

export type DiscoveryQuote = {
  id: string
  speaker: string
  text: string
  at: number
}

export type ProposalDiscoveryProps = {
  columns: readonly DiscoveryColumn[]
  unknownsTitle?: string
  unknowns: readonly DiscoveryUnknown[]
  quotesTitle?: string
  quotes: readonly DiscoveryQuote[]
  playLabel?: string
  conflictTitle?: string
  conflictBody?: string
  clarifyLabel?: string
  onClarify?: () => void
  audioLabel?: string
  peaks?: number[]
  /** Recording length in seconds, used when the player has no file yet. */
  duration?: number
  onSeek?: (seconds: number) => void
  className?: string
}

function clock(seconds: number) {
  const total = Math.max(0, Math.floor(seconds))
  const minutes = Math.floor(total / 60)
  const rest = total % 60
  return `${minutes}:${rest.toString().padStart(2, "0")}`
}

export function ProposalDiscovery({
  columns,
  unknownsTitle = "Still open",
  unknowns,
  quotesTitle = "Quotes",
  quotes,
  playLabel = "Play",
  conflictTitle,
  conflictBody,
  clarifyLabel = "Clarify",
  onClarify,
  audioLabel = "Call recording",
  peaks,
  duration,
  onSeek,
  className,
}: ProposalDiscoveryProps) {
  const player = React.useRef<AudioPlayerHandle>(null)

  const seek = (seconds: number) => {
    player.current?.seek(seconds)
    onSeek?.(seconds)
  }

  return (
    <div data-slot="proposal-discovery" className={cn("grid min-w-0 gap-4", className)}>
      <div className="rounded-xl border border-border bg-card p-3">
        <p className="mb-2 text-sm font-medium">{audioLabel}</p>
        <AudioPlayer ref={player} peaks={peaks} duration={duration} onTimeUpdate={onSeek} />
      </div>
      <div className="grid min-w-0 gap-3 sm:grid-cols-2 xl:grid-cols-3">
        {columns.map((column) => (
          <section key={column.id} className="min-w-0 rounded-xl border border-border bg-card p-3" aria-label={column.title}>
            <h2 className="text-sm font-medium">{column.title}</h2>
            <ul className="mt-2 flex flex-col gap-2">
              {column.items.map((item) => (
                <li key={item.id} className="text-sm text-muted-foreground">
                  <span className="text-foreground">{item.text}</span>
                  {item.at !== undefined ? (
                    <button
                      type="button"
                      className="ms-2 text-xs text-primary underline-offset-2 hover:underline"
                      onClick={() => seek(item.at ?? 0)}
                    >
                      {clock(item.at)}
                    </button>
                  ) : null}
                </li>
              ))}
            </ul>
          </section>
        ))}
      </div>
      {unknowns.length > 0 ? (
        <section className="rounded-xl border border-border bg-muted/40 p-3">
          <h2 className="text-sm font-medium">{unknownsTitle}</h2>
          <ul className="mt-2 flex flex-col gap-2">
            {unknowns.map((item) => (
              <li key={item.id} className="flex flex-wrap items-center gap-2 text-sm">
                <span className="min-w-0 flex-1">{item.text}</span>
                <span className="rounded-full bg-muted px-2 py-0.5 text-xs text-muted-foreground">{item.badge}</span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      {quotes.length > 0 ? (
        <section aria-label={quotesTitle} className="grid gap-2">
          <h2 className="text-sm font-medium">{quotesTitle}</h2>
          {quotes.map((quote) => (
            <blockquote key={quote.id} className="flex min-w-0 items-start gap-2 rounded-xl border border-border p-3">
              <Button
                type="button"
                size="icon-sm"
                variant="secondary"
                aria-label={`${playLabel} ${clock(quote.at)}`}
                onClick={() => seek(quote.at)}
              >
                <Play />
              </Button>
              <div className="min-w-0">
                <p className="text-xs text-muted-foreground">
                  {quote.speaker} · {clock(quote.at)}
                </p>
                <p className="text-sm wrap-break-word">“{quote.text}”</p>
              </div>
            </blockquote>
          ))}
        </section>
      ) : null}
      {conflictTitle ? (
        <div role="alert" className="flex gap-2 rounded-xl border border-destructive/30 bg-destructive/10 p-3 text-sm">
          <AlertTriangle className="mt-0.5 size-4 shrink-0 text-destructive" />
          <div className="min-w-0">
            <p className="font-medium">{conflictTitle}</p>
            {conflictBody ? <p className="text-muted-foreground">{conflictBody}</p> : null}
          </div>
        </div>
      ) : null}
      <div>
        <Button type="button" onClick={onClarify}>
          {clarifyLabel}
        </Button>
      </div>
    </div>
  )
}

"use client"

// Adapted from LocalMode UI (MIT) — apps/ui/registry/localmode/audio/audio-scrub-player/audio-scrub-player.tsx

import * as React from "react"
import { Download, Pause, Play } from "lucide-react"

import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"

export type AudioPlayerHandle = {
  play: () => void
  pause: () => void
  seek: (seconds: number) => void
}

export type AudioPlayerProps = {
  src?: string
  blob?: Blob
  peaks?: number[]
  /** Used when the file has no duration yet, so the waveform can still be scrubbed. */
  duration?: number
  onTimeUpdate?: (seconds: number) => void
  downloadName?: string
  className?: string
  classNames?: { root?: string; track?: string }
}

const SPEEDS = [0.75, 1, 1.25, 1.5, 2]

export function useObjectUrl(blob?: Blob) {
  const url = React.useMemo(() => (blob ? URL.createObjectURL(blob) : undefined), [blob])
  React.useEffect(() => {
    if (!url) return
    return () => URL.revokeObjectURL(url)
  }, [url])
  return url
}

function clock(seconds: number) {
  if (!Number.isFinite(seconds) || seconds < 0) return "0:00"
  const total = Math.floor(seconds)
  const minutes = Math.floor(total / 60)
  const rest = total % 60
  return `${minutes}:${rest.toString().padStart(2, "0")}`
}

export const AudioPlayer = React.forwardRef<AudioPlayerHandle, AudioPlayerProps>(function AudioPlayer(
  { src, blob, peaks, duration: durationHint = 0, onTimeUpdate, downloadName = "audio", className, classNames },
  ref,
) {
  const objectUrl = useObjectUrl(blob)
  const source = src ?? objectUrl
  const audioRef = React.useRef<HTMLAudioElement>(null)
  const [playing, setPlaying] = React.useState(false)
  const [time, setTime] = React.useState(0)
  const [mediaDuration, setMediaDuration] = React.useState(0)
  const [speed, setSpeed] = React.useState(1)
  const duration = mediaDuration > 0 ? mediaDuration : durationHint

  React.useImperativeHandle(ref, () => ({
    play: () => void audioRef.current?.play(),
    pause: () => audioRef.current?.pause(),
    seek: (seconds: number) => {
      const audio = audioRef.current
      if (!audio) return
      const next = Math.min(Math.max(0, seconds), duration || seconds)
      if (audio.duration > 0) audio.currentTime = next
      setTime(next)
      onTimeUpdate?.(next)
    },
  }))

  const seek = (seconds: number) => {
    const audio = audioRef.current
    if (!audio) return
    const next = Math.min(Math.max(0, seconds), duration || seconds)
    if (audio.duration > 0) audio.currentTime = next
    setTime(next)
    onTimeUpdate?.(next)
  }

  return (
    <div
      className={cn("flex min-w-0 flex-wrap items-center gap-2 rounded-lg border border-border bg-card p-2", className, classNames?.root)}
      onKeyDown={(event) => {
        if (event.key === " " && event.target === event.currentTarget) {
          event.preventDefault()
          if (playing) audioRef.current?.pause()
          else void audioRef.current?.play()
        }
      }}
      tabIndex={0}
    >
      <audio
        ref={audioRef}
        src={source}
        preload="metadata"
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onTimeUpdate={(event) => {
          if (!(event.currentTarget.duration > 0)) return
          setTime(event.currentTarget.currentTime)
          onTimeUpdate?.(event.currentTarget.currentTime)
        }}
        onLoadedMetadata={(event) => {
          const next = event.currentTarget.duration
          if (next > 0) setMediaDuration(next)
        }}
      />
      <Button type="button" size="icon-sm" variant="outline" aria-label={playing ? "Pause" : "Play"} onClick={() => (playing ? audioRef.current?.pause() : void audioRef.current?.play())}>
        {playing ? <Pause data-icon="inline-start" /> : <Play data-icon="inline-start" />}
      </Button>
      <span className="w-10 font-mono text-xs tabular-nums">{clock(time)}</span>
      <div
        role="slider"
        tabIndex={0}
        aria-valuemin={0}
        aria-valuemax={Math.round(duration || 0)}
        aria-valuenow={Math.round(time)}
        aria-valuetext={`${clock(time)} of ${clock(duration)}`}
        aria-label="Seek"
        className={cn("relative h-8 min-w-24 flex-1", classNames?.track)}
        onKeyDown={(event) => {
          const step = event.shiftKey ? 15 : 5
          if (event.key === "ArrowRight") seek(time + step)
          if (event.key === "ArrowLeft") seek(time - step)
          if (event.key === "Home") seek(0)
          if (event.key === "End") seek(duration)
        }}
        onPointerDown={(event) => {
          const rect = event.currentTarget.getBoundingClientRect()
          const ratio = (event.clientX - rect.left) / rect.width
          seek(ratio * (duration || 0))
        }}
      >
        <span className="absolute inset-x-0 top-1/2 h-1 -translate-y-1/2 rounded-full bg-muted" />
        {peaks ? (
          <span className="absolute inset-x-0 top-1 flex h-6 items-end gap-px">
            {peaks.map((peak, index) => (
              <span key={index} className="flex-1 rounded-sm bg-muted-foreground/40" style={{ height: `${Math.max(8, peak * 100)}%` }} />
            ))}
          </span>
        ) : null}
        <span className="absolute top-1/2 left-0 h-1 -translate-y-1/2 rounded-full bg-primary" style={{ width: duration ? `${(time / duration) * 100}%` : "0%" }} />
      </div>
      <span className="w-10 font-mono text-xs text-muted-foreground tabular-nums">{clock(duration)}</span>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button type="button" size="sm" variant="ghost" aria-label="Playback speed">
            {speed}×
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent>
          {SPEEDS.map((item) => (
            <DropdownMenuItem
              key={item}
              onSelect={() => {
                setSpeed(item)
                if (audioRef.current) audioRef.current.playbackRate = item
              }}
            >
              {item}×
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
      {source ? (
        <Button type="button" size="icon-sm" variant="ghost" aria-label="Download audio" asChild>
          <a href={source} download={downloadName}>
            <Download data-icon="inline-start" />
          </a>
        </Button>
      ) : null}
    </div>
  )
})
